<script>
const albumsData = [
{ id: 'cc', title: 'Cowboy Carter', artist: 'Beyoncé', year: '2024', artClass: 'art-cowboy',
tracks: [
{ t: 'AMERIICAN REQUIEM', d: '5:25', l: "Nothing really ends for things to stay the same..." },
{ t: 'BLACKBIIRD', d: '2:11' }, { t: '16 CARRIAGES', d: '3:47' }, { t: 'PROTECTOR', d: '3:04' },
