tracks: [
{ t: 'Break Up Song', d: '3:20' }, { t: 'Holiday', d: '3:33' }, { t: 'Sweet Melody', d: '3:33' },
{ t: 'Confetti', d: '3:05' }, { t: 'Happiness', d: '3:17' }, { t: 'Not a Pop Song', d: '2:59' },
{ t: 'Nothing But My Feelings', d: '2:42' }, { t: 'Gloves Up', d: '2:47' }, { t: 'A Mess (Happy 4 U)', d: '3:29' }
]
},
{ id: 'lm5', title: 'LM5', artist: 'Little Mix', year: '2018', artClass: 'art-lm5',
tracks: [
{ t: 'The National Manthem', d: '0:29' }, { t: 'Woman Like Me', d: '3:49' }, { t: 'Think About Us', d: '3:55' },
{ t: 'Strip', d: '3:19' }, { t: 'Monster In Me', d: '3:45' }, { t: 'Joan of Arc', d: '3:11' },
{ t: 'Love a Girl Right', d: '3:02' }, { t: 'American Boy', d: '3:11' }, { t: 'Told You So', d: '3:12' },
{ t: 'Wasabi', d: '2:34' }
]
}
];
let state = { playing: false, currentAlbum: null, currentTrackIdx: 0, playerOpen: false, progress: 0 };
let audioInterval;
const dObj = (id) => document.getElementById(id);
const elAlbumGrid = dObj('album-grid');
const elSearchResults = dObj('search-results');
const elTrackList = dObj('track-list-view');
const elMiniPlayer = dObj('mini-player-container');
const elFullPlayer = dObj('full-player');
const elProgressBar = dObj('progress-fill');
function init() {
renderLibrary();
setupTabs();
setupSearch();
setupPlayerInteractions();
requestAnimationFrame(updateProgress);
}
function renderLibrary() {
elAlbumGrid.innerHTML = albumsData.map(a => `
<div class="album-card" onclick="openAlbum('${a.id}')">
<div class="album-art"><div class="album-art-inner ${a.artClass}"></div></div>
<div class="album-title">${a.title}</div>
<div class="album-artist">${a.artist}</div>
</div>`).join('');
}
function openAlbum(id) {
const album = albumsData.find(a => a.id === id);
state.currentAlbum = album;
dObj('header-title').innerText = album.title;
dObj('header-meta').innerText = `${album.artist} • ${album.year}`;
dObj('header-art').className = `header-art ${album.artClass}`;
const rows = album.tracks.map((t, i) => `
<div class="track-row" onclick="playTrack(${i})">
<div class="track-num">${i + 1}</div>
<div class="track-info"><div class="track-name">${t.t}</div><div class="track-artist-small">${album.artist}</div></div>
<div class="track-duration">${t.d}</div>
</div>`).join('');
dObj('track-rows-container').innerHTML = rows;
elTrackList.classList.add('visible');
setTimeout(() => dObj('track-header').classList.add('animate'), 100);
}
dObj('back-btn').onclick = () => {
elTrackList.classList.remove('visible');
dObj('track-header').classList.remove('animate');
};
function playTrack(idx) {
state.currentTrackIdx = idx;
state.playing = true;
state.progress = 0;
updatePlayerUI();
elMiniPlayer.classList.remove('hidden');
if(navigator.vibrate) navigator.vibrate(15);
startSimulatedAudio();
}
function updatePlayerUI() {
const track = state.currentAlbum.tracks[state.currentTrackIdx];
const artClass = state.currentAlbum.artClass;
dObj('mini-title').innerText = track.t;
dObj('mini-artist').innerText = state.currentAlbum.artist;
dObj('mini-art').className = `mini-art ${artClass}`;
dObj('fp-title').innerText = track.t;
dObj('fp-artist').innerText = state.currentAlbum.artist;
dObj('fp-art').className = `fp-art ${artClass}`;
dObj('duration-time').innerText = track.d;
dObj('lyrics-snippet').innerText = track.l ? track.l : "Szöveg nem elérhető ehhez a dalhoz...";
updatePlayIcons();
}
function updatePlayIcons() {
const path = state.playing ? "M6 19h4V5H6v14zm8-14v14h4V5h-4z" : "M8 5v14l11-7z";
dObj('mini-play-btn').querySelector('path').setAttribute('d', path);
dObj('fp-play-btn').querySelector('path').setAttribute('d', path);
}
function togglePlay() {
state.playing = !state.playing;
updatePlayIcons();
if(state.playing) startSimulatedAudio(); else clearInterval(audioInterval);
if(navigator.vibrate) navigator.vibrate(10);
}
function startSimulatedAudio() {
clearInterval(audioInterval);
audioInterval = setInterval(() => {
if(!state.playing) return;
state.progress += 0.1;
if(state.progress >= 100) { nextTrack(); }
}, 100);
}
function updateProgress() {
if(state.playing) {
elProgressBar.style.width = `${state.progress}%`;
const durParts = state.currentAlbum.tracks[state.currentTrackIdx].d.split(':');
const totalSec = parseInt(durParts[0])*60 + parseInt(durParts[1]);
const currSec = Math.floor((state.progress / 100) * totalSec);
const min = Math.floor(currSec / 60);
const sec = currSec % 60;
